create temporary table _league_question_seed (
  source_key text primary key,
  category_slug text not null,
  question_text text not null,
  difficulty public.question_difficulty not null,
  options text[] not null,
  correct_position smallint not null,
  correct_answer text not null,
  explanation text,
  source_url text,
  source_name text,
  image_source_url text,
  subtopic text,
  point_value integer not null
) on commit drop;

insert into _league_question_seed(
  source_key, category_slug, question_text, difficulty, options,
  correct_position, correct_answer, explanation, source_url, source_name,
  image_source_url, subtopic, point_value
)
select
  source_key,
  category_slug,
  question_text,
  difficulty::public.question_difficulty,
  array(select jsonb_array_elements_text(options)),
  correct_position::smallint,
  correct_answer,
  explanation,
  source_url,
  source_name,
  image_source_url,
  subtopic,
  point_value
