  source_key text,
  category_slug text,
  question_text text,
  difficulty text,
  options jsonb,
  correct_position integer,
  correct_answer text,
  explanation text,
  source_url text,
  source_name text,
  image_source_url text,
  subtopic text,
  point_value integer
);

create temporary table _league_question_inserted (
  id uuid primary key,
  category_id uuid not null,
  normalized_text text not null
) on commit drop;

with inserted as (
  insert into public.questions(
    question_text, question_type, category_id, difficulty, correct_answer,
    explanation, source_url, source_name, verified_at, point_value,
    status, needs_review, gameplay_type, question_format,
    media_rights_status, offline_practice_eligible, competitive_eligible,
    mechanic_config, published_at
  )
  select
    seed.question_text,
    'text'::public.question_type,
    category.id,
    seed.difficulty,
    seed.correct_answer,
    seed.explanation,
    seed.source_url,
    seed.source_name,
    now(),
    seed.point_value,
    'published'::public.question_status,
    false,
    'classic',
    'multiple_choice',
    'none',
    true,
    false,
    jsonb_strip_nulls(jsonb_build_object(
      'source_key', seed.source_key,
      'subtopic', seed.subtopic,
      'editorial_image_url', seed.image_source_url,
      'editorial_image_rights', case when seed.image_source_url is null then null else 'unverified' end
    )),
    now()
  from _league_question_seed as seed
  join public.categories as category on category.slug::text = seed.category_slug
  on conflict (content_hash) where status <> 'archived' do nothing
  returning id, category_id, normalized_text
)
insert into _league_question_inserted(id, category_id, normalized_text)
select id, category_id, normalized_text from inserted;

insert into public.question_options(question_id, option_text, position)
select
  inserted.id,
  option_row.option_text,
  option_row.position::smallint
from _league_question_inserted as inserted
join public.categories as category on category.id = inserted.category_id
join _league_question_seed as seed
  on seed.category_slug = category.slug::text
 and public.normalize_question_text(seed.question_text) = inserted.normalized_text
cross join lateral unnest(seed.options) with ordinality as option_row(option_text, position)
on conflict (question_id, position) do nothing;

update public.questions as question
set
  correct_option_id = option.id,
  correct_answer = option.option_text
from _league_question_inserted as inserted
join public.categories as category on category.id = inserted.category_id
join _league_question_seed as seed
  on seed.category_slug = category.slug::text
 and public.normalize_question_text(seed.question_text) = inserted.normalized_text
join public.question_options as option
  on option.question_id = inserted.id
 and option.position = seed.correct_position
where question.id = inserted.id;
